SELECT CASE WHEN credit_limit >= 14600 THEN 'high' WHEN credit_limit >= 6300 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, MAX(signup_date) AS last_signup_date FROM customers WHERE credit_limit <= 11300 AND segment IN ('Consumer', 'SMB', 'Corporate') GROUP BY CASE WHEN credit_limit >= 14600 THEN 'high' WHEN credit_limit >= 6300 THEN 'mid' ELSE 'low' END ORDER BY last_signup_date, credit_limit_bucket;
